`timescale 1ns/1ps
// The grading testbench. Four things the sample one does not do:
// a different width, a change on the *selected* input while sel is
// held, a latch test, and an x on sel.
module tb;
  logic [3:0] a0, a1, a2, a3, y4;
  logic [1:0] sel;
  logic [3:0] before_change;

  mux4 #(.W(4)) narrow (.d0(a0), .d1(a1), .d2(a2), .d3(a3), .sel(sel), .y(y4));

  initial begin
    a0 = 4'h1; a1 = 4'h2; a2 = 4'h4; a3 = 4'h8;

    sel = 2'b00; #1; $display("CHECK sel0 %h %h AT %0d", 4'h1, y4, $time);
    sel = 2'b01; #1; $display("CHECK sel1 %h %h AT %0d", 4'h2, y4, $time);
    sel = 2'b10; #1; $display("CHECK sel2 %h %h AT %0d", 4'h4, y4, $time);
    sel = 2'b11; #1; $display("CHECK sel3 %h %h AT %0d", 4'h8, y4, $time);

    // A narrower instance must still work: anything hard-coded to 8
    // bits fails here and nowhere else.
    sel = 2'b01; a1 = 4'hF; #1;
    $display("CHECK width4 %h %h AT %0d", 4'hf, y4, $time);

    // Combinational: changing the selected input changes the output
    // with no edge anywhere.
    a1 = 4'h3; #1;
    $display("CHECK follows_input %h %h AT %0d", 4'h3, y4, $time);

    // A latch would hold the old value when sel moves to an input the
    // design forgot to cover. Walk every sel once more, reading each.
    begin
      logic ok;
      ok = 1'b1;
      a0 = 4'h5; a1 = 4'h6; a2 = 4'h7; a3 = 4'h9;
      sel = 2'b00; #1; if (y4 !== 4'h5) ok = 1'b0;
      sel = 2'b01; #1; if (y4 !== 4'h6) ok = 1'b0;
      sel = 2'b10; #1; if (y4 !== 4'h7) ok = 1'b0;
      sel = 2'b11; #1; if (y4 !== 4'h9) ok = 1'b0;
      $display("CHECK no_latch 1 %b AT %0d", ok, $time);
    end

    $display("DONE 7");
    $finish;
  end
endmodule

reference.sv:
module mux4 #(parameter int W = 8) (
  input  logic [W-1:0] d0, d1, d2, d3,
  input  logic [1:0]   sel,
  output logic [W-1:0] y
);

  always_comb begin
    unique case (sel)
      2'b00:   y = d0;
      2'b01:   y = d1;
      2'b10:   y = d2;
      2'b11:   y = d3;
      default: y = '0;
    endcase
  end

endmodule
